"""File-level storage primitives: layout, locking, manifest and cache.

Two on-disk layouts are supported:

* segment store -- ``path`` is a directory holding ordered segment files
  (``seg-00000001.jsonl`` ...), an atomic ``manifest.json`` and a tamper
  evident verify cache;
* legacy single file -- ``path`` is a plain JSON-lines file, exactly as the
  pre-extension log wrote it. Segmentation is opt-in there via ``rotate()``,
  which migrates the file into a segment store at the same path.
"""

from __future__ import annotations

import contextlib
import fcntl
import hashlib
import json
import os
import time
from typing import Any, Iterator, Optional

from . import record as rec

_ENCODING = "utf-8"
LOCK_NAME = ".lock"
MANIFEST_NAME = "manifest.json"
CACHE_NAME = ".verify-cache"
SEG_PREFIX = "seg-"
SEG_SUFFIX = ".jsonl"
FIRST_SEQ = 1
EMPTY_SHA256 = hashlib.sha256(b"").hexdigest()
_CHUNK = 1 << 20
_LOCK_POLL_SECONDS = 0.01


def seg_name(seq: int) -> str:
    return f"{SEG_PREFIX}{seq:08d}{SEG_SUFFIX}"


def seg_seq(name: str) -> Optional[int]:
    if not (name.startswith(SEG_PREFIX) and name.endswith(SEG_SUFFIX)):
        return None
    middle = name[len(SEG_PREFIX) : -len(SEG_SUFFIX)]
    if len(middle) != 8 or not middle.isdigit():
        return None
    return int(middle)


def atomic_write_text(directory: str, name: str, text: str) -> None:
    """Durably replace ``directory/name`` with ``text`` (fsync + rename)."""
    final_path = os.path.join(directory, name)
    tmp_name = f".{name}.tmp"
    tmp_path = os.path.join(directory, tmp_name)
    with open(tmp_path, "w", encoding=_ENCODING, newline="") as handle:
        handle.write(text)
        handle.flush()
        os.fsync(handle.fileno())
    os.replace(tmp_path, final_path)
    fsync_dir(directory)


def fsync_dir(directory: str) -> None:
    flags = os.O_RDONLY
    if hasattr(os, "O_DIRECTORY"):
        flags |= os.O_DIRECTORY
    fd = os.open(directory, flags)
    try:
        os.fsync(fd)
    finally:
        os.close(fd)


def file_fingerprint(path: str) -> tuple[int, str]:
    """Return (size, sha256) over the whole file in one streaming pass."""
    h = hashlib.sha256()
    size = 0
    with open(path, "rb") as handle:
        while True:
            chunk = handle.read(_CHUNK)
            if not chunk:
                break
            size += len(chunk)
            h.update(chunk)
    return size, h.hexdigest()


def verify_windows(path: str, parts: list[dict]) -> bool:
    """Verify each retained byte window (part) of a (possibly merged) segment.

    A merged segment keeps the size and sha256 of every source segment as
    verification material; the merged bytes are the exact concatenation of
    those windows, so a single streaming read re-checks every source segment.
    """
    try:
        actual_size = os.path.getsize(path)
    except OSError:
        raise
    if actual_size != sum(part["size"] for part in parts):
        return False
    with open(path, "rb") as handle:
        for part in parts:
            h = hashlib.sha256()
            remaining = part["size"]
            while remaining:
                chunk = handle.read(min(_CHUNK, remaining))
                if not chunk:
                    return False
                h.update(chunk)
                remaining -= len(chunk)
            if h.hexdigest() != part["sha256"]:
                return False
    return True


class Layout:
    """Resolved view of where the log data and its lock live."""

    def __init__(self, root: str, kind: str):
        self.root = root
        self.kind = kind  # "dir" or "file"

    @property
    def lock_path(self) -> str:
        if self.kind == "dir":
            return os.path.join(self.root, LOCK_NAME)
        directory = os.path.dirname(self.root) or "."
        return os.path.join(directory, "." + os.path.basename(self.root) + ".lock")

    @property
    def manifest_path(self) -> str:
        return os.path.join(self.root, MANIFEST_NAME)

    @property
    def cache_path(self) -> str:
        return os.path.join(self.root, CACHE_NAME)

    def segment_path(self, name: str) -> str:
        return os.path.join(self.root, name)


def resolve_existing(path: str) -> Optional[Layout]:
    """Resolve an existing log path, or return None when nothing is there."""
    if os.path.isdir(path):
        return Layout(path, "dir")
    if os.path.isfile(path):
        return Layout(path, "file")
    return None


def ensure_lockfile(lock_path: str) -> None:
    # O_CREAT without O_EXCL: harmless if another process created it first.
    fd = os.open(lock_path, os.O_RDWR | os.O_CREAT, 0o600)
    os.close(fd)


@contextlib.contextmanager
def file_lock(lock_path: str, *, timeout: Optional[float]) -> Iterator[None]:
    """Serialize access to one log with a process-shared file lock.

    A timeout that elapses raises ``TimeoutError`` (an ``OSError`` subclass);
    callers treat it like any other system error.
    """
    ensure_lockfile(lock_path)
    fd = os.open(lock_path, os.O_RDWR)
    acquired = False
    try:
        deadline = None if timeout is None else time.monotonic() + timeout
        while True:
            try:
                fcntl.flock(fd, fcntl.LOCK_EX | fcntl.LOCK_NB)
                acquired = True
                break
            except BlockingIOError:
                if deadline is not None and time.monotonic() >= deadline:
                    raise TimeoutError(f"audit log lock busy: {lock_path}")
                time.sleep(_LOCK_POLL_SECONDS)
        yield
    finally:
        if acquired:
            with contextlib.suppress(OSError):
                fcntl.flock(fd, fcntl.LOCK_UN)
        os.close(fd)


# ---------------------------------------------------------------------------
# Manifest
# ---------------------------------------------------------------------------


def default_manifest(first: str) -> dict:
    return {"version": 1, "active": first, "segments": []}


def load_manifest(layout: Layout) -> Optional[dict]:
    try:
        with open(layout.manifest_path, "rb") as handle:
            raw = handle.read()
    except FileNotFoundError:
        return None
    try:
        manifest = json.loads(raw.decode(_ENCODING))
    except (UnicodeDecodeError, ValueError) as exc:
        raise ValueError("malformed audit manifest") from exc
    if not _valid_manifest(manifest):
        raise ValueError("malformed audit manifest")
    return manifest


def _valid_manifest(manifest: Any) -> bool:
    if not isinstance(manifest, dict):
        return False
    if manifest.get("version") != 1 or not isinstance(manifest.get("active"), str):
        return False
    segments = manifest.get("segments")
    if not isinstance(segments, list) or not segments:
        return False
    for index, segment in enumerate(segments):
        if not isinstance(segment, dict):
            return False
        if not isinstance(segment.get("name"), str) or not isinstance(
            segment.get("sealed"), bool
        ):
            return False
        parts = segment.get("parts")
        if not isinstance(parts, list) or not parts:
            return False
        for part in parts:
            if not isinstance(part, dict):
                return False
            if (
                not isinstance(part.get("name"), str)
                or not isinstance(part.get("size"), int)
                or not isinstance(part.get("sha256"), str)
            ):
                return False
        if index == len(segments) - 1:
            if segment["name"] != manifest["active"] or segment["sealed"]:
                return False
        elif not segment["sealed"]:
            return False
    return True


def save_manifest(layout: Layout, manifest: dict) -> None:
    atomic_write_text(layout.root, MANIFEST_NAME, rec.canonical_json(manifest))


# ---------------------------------------------------------------------------
# Incremental verify cache
# ---------------------------------------------------------------------------


def cache_tag_payload(version: int, segments: dict) -> bytes:
    return rec.canonical_json({"version": version, "segments": segments}).encode(
        _ENCODING
    )


def load_cache(layout: Layout) -> Optional[dict]:
    """Load the verify cache or return None when absent.

    A present cache whose authentication tag fails to verify is tampering:
    ValueError is raised rather than silently rebuilding, because a rebuilt
    cache could otherwise report a healthy log the attacker tried to cover.
    """
    try:
        with open(layout.cache_path, "rb") as handle:
            raw = handle.read()
    except FileNotFoundError:
        return None
    try:
        cache = json.loads(raw.decode(_ENCODING))
    except (UnicodeDecodeError, ValueError) as exc:
        raise ValueError("tampered audit cache") from exc
    if not isinstance(cache, dict) or cache.get("version") != 1:
        raise ValueError("tampered audit cache")
    tag = cache.get("tag")
    segments = cache.get("segments")
    if not isinstance(tag, str) or not isinstance(segments, dict):
        raise ValueError("tampered audit cache")
    expected = hashlib.sha256(cache_tag_payload(1, segments)).hexdigest()
    if not hmac_compare(tag, expected):
        raise ValueError("tampered audit cache")
    if not _valid_cache_segments(segments):
        raise ValueError("tampered audit cache")
    return {"version": 1, "segments": segments, "tag": tag}


def hmac_compare(actual: str, expected: str) -> bool:
    if len(actual) != len(expected):
        return False
    result = 0
    for a, b in zip(actual, expected):
        result |= ord(a) ^ ord(b)
    return result == 0


def _valid_cache_segments(segments: Any) -> bool:
    if not isinstance(segments, dict):
        return False
    for name, entry in segments.items():
        if not isinstance(name, str) or not isinstance(entry, dict):
            return False
        if not isinstance(entry.get("records"), int) or entry["records"] < 0:
            return False
        parts = entry.get("parts")
        if not isinstance(parts, list) or not parts:
            return False
        for part in parts:
            if not isinstance(part, dict):
                return False
            if (
                not isinstance(part.get("name"), str)
                or not isinstance(part.get("size"), int)
                or not isinstance(part.get("sha256"), str)
            ):
                return False
        tenants = entry.get("tenants")
        if not isinstance(tenants, dict):
            return False
        for tenant, state in tenants.items():
            if not isinstance(tenant, str) or not isinstance(state, dict):
                return False
            if (
                not isinstance(state.get("count"), int)
                or not isinstance(state.get("digest"), str)
                or not isinstance(state.get("bad"), int)
                or state["count"] < 0
                or state["bad"] < -1
            ):
                return False
    return True


def save_cache(layout: Layout, segments: dict) -> None:
    tag = hashlib.sha256(cache_tag_payload(1, segments)).hexdigest()
    payload = {"version": 1, "segments": segments, "tag": tag}
    atomic_write_text(layout.root, CACHE_NAME, rec.canonical_json(payload))


# ---------------------------------------------------------------------------
# Record scanning
# ---------------------------------------------------------------------------


def scan_segment_lines(path: str) -> list[str]:
    """Read one segment file and split it into raw record lines.

    Mirrors the single-file rules: decode errors and a trailing partial line
    are bad lines and raise ValueError rather than being skipped.
    """
    with open(path, "rb") as handle:
        raw = handle.read()
    try:
        text = raw.decode(_ENCODING)
    except UnicodeDecodeError as exc:
        raise ValueError("malformed audit record") from exc
    return rec.split_records(text)

