# ------------------------------------------------------------------
# Incremental verification walk
# ------------------------------------------------------------------

def _walk(
    self, units: list[dict], layout: st.Layout, *, trust_growth: bool = False
) -> tuple[dict[str, tuple[int, int, int]], dict]:
    """Walk every unit in order, reusing authenticated cached prefixes.

    Returns ``(states, entries)`` where states maps tenant to
    ``(count, head_digest, first_bad)`` and entries maps unit name to a
    cache entry. A unit unchanged since caching costs no hashing; a
    grown active unit only hashes the appended suffix instead of the
    whole file (writers are flock-serialized and only ever O_APPEND, so
    the covered prefix cannot legitimately change). Any other change --
    a same-size rewrite, a shrink, or a touched sealed unit -- forces
    window re-verification, attributing damaged windows to the tenants
    whose records they hold so one tenant's damage never changes another
    tenant's verdict while ``first_bad`` stays global.
    """
    cache = st.load_cache(layout)
    cached = {} if cache is None else cache["segments"]
    states: dict[str, list] = {}
    entries: dict[str, dict] = {}
    total_records = 0

    for unit in units:
        if unit.get("initialize"):
            continue
        name = unit["name"]
        path = unit["path"]
        try:
            stat = os.stat(path)
        except FileNotFoundError:
            if name == _FILE_UNIT:
                # The legacy file is created by the O_APPEND open below;
                # a first append on a not-yet-existing path is valid.
                continue
            # A segment listed by the manifest must exist.
            raise
        entry = cached.get(name)

        if entry is not None and self._stat_fresh(entry, stat):
            # Unchanged since the cached walk: adopt its states without
            # reading or hashing any record bytes.
            for tenant, state in entry["tenants"].items():
                states[tenant] = list(state)
            total_records = entry["records"]
            entries[name] = _cache_entry(
                total_records, stat, entry["parts"], states
            )
            continue

        if entry is not None:
            grew = stat.st_size > entry["size"] and not unit["sealed"]
            if grew:
                # Appended-only growth.
                #
                # Prefix safety: an external verifier first re-checks the
                # cached prefix windows (writers are flock-serialized and
                # O_APPEND-only, so in normal operation the writer warmed
                # the cache and this branch is not even taken -- growth
                # without a fresh cache means a crashed writer or an
                # out-of-band change); the append hot path, which holds
                # the exclusive lock and validated/flushed those bytes
                # itself, skips that check.
                #
                # Either way only the suffix is parsed and chained. The
                # active unit accumulates one suffix window per growth and
                # collapses them into a single whole-unit window
                # periodically, so the cache stays small and a long log
                # is never fully rehashed per append or per verify.
                windows = list(entry["parts"])
                if not trust_growth and not st.verify_prefix_windows(
                    path, windows
                ):
                    # Covered prefix bytes changed: full re-verification
                    # attributes the damage by window and tenant.
                    walked, parts = self._walk_bytes(
                        unit, windows, states, force_verify=True
                    )
                    total_records += walked
                    entries[name] = _cache_entry(
                        total_records, stat, parts, states
                    )
                    continue

                for tenant, state in entry["tenants"].items():
                    states[tenant] = list(state)
                with open(path, "rb") as handle:
                    handle.seek(entry["size"])
                    tail = handle.read()
                records = st.decode_records(tail)
                self._apply_records(records, states)
                total_records = entry["records"] + len(records)
                windows.append(
                    {"name": name, "size": len(tail), "sha256": _sha256(tail)}
                )
                if len(windows) > _MAX_ACTIVE_WINDOWS:
                    with open(path, "rb") as handle:
                        whole = handle.read()
                    windows = [
                        {
                            "name": name,
                            "size": len(whole),
                            "sha256": _sha256(whole),
                        }
                    ]
                entries[name] = _cache_entry(
                    total_records, stat, windows, states
                )
                continue

            # Same-size rewrite, shrink, or any change to a sealed unit:
            # re-verify every window and re-walk.
            walked, parts = self._walk_bytes(
                unit, entry["parts"], states, force_verify=True
            )
        else:
            # Cold unit: sealed material is verified once; active/legacy
            # units are fingerprinted as a single growing window.
            walked, parts = self._walk_bytes(
                unit, unit["parts"], states, force_verify=bool(unit["parts"])
            )
        total_records += walked
        entries[name] = _cache_entry(total_records, stat, parts, states)

    st.save_cache(layout, entries)
    return (
        {tenant: (state[0], state[1], state[2]) for tenant, state in states.items()},
        entries,
    )

        )

    @staticmethod
    def _stat_fresh(entry: dict, stat: os.stat_result) -> bool:
        # size + mtime prove an unchanged append-only file. A same-size
        # rewrite that leaves mtime untouched but bumps ctime (which utimes
        # cannot restore) forces re-verification.
        if entry["size"] != stat.st_size or entry["mtime_ns"] != stat.st_mtime_ns:
            return False
        return entry["ctime_ns"] == stat.st_ctime_ns or entry["size"] == 0

    @staticmethod
    def _entry_parts(unit: dict, name: str, raw: bytes) -> list[dict]:
        if unit["sealed"]:
            return [dict(part) for part in unit["parts"]]
        return [{"name": name, "size": len(raw), "sha256": _sha256(raw)}]

    def _walk_bytes(
        self,
        unit: dict,
        windows: list[dict],
        states: dict[str, list],
        *,
        force_verify: bool,
    ) -> tuple[int, list[dict]]:
        """Parse and chain one unit's bytes, attributing damaged windows.

        Returns ``(record_count, cache_parts)``. Each preserved byte window
        whose sha256 no longer matches marks the first of its records bad for
        every tenant appearing in it: chain damage yields a global index,
        while tenants absent from a damaged window keep their verdict. An
        unparsable line is still a hard ``ValueError``.
        """
        path = unit["path"]
        with open(path, "rb") as handle:
            raw = handle.read()
        try:
            text = raw.decode(_ENCODING)
        except UnicodeDecodeError as exc:
            raise ValueError("malformed audit record") from exc
