        # whole lines, so on a healthy unit each span sits inside one window.
        spans: list[tuple[int, int]] = []
        pos = 0
        for line in lines:
            length = len((line + "\n").encode(_ENCODING))
            spans.append((pos, pos + length))
            pos += length

