class CountingHash:
    """Stand-in for hashlib.sha256 counting bytes fed to updates."""

    def __init__(self, data: bytes = b"") -> None:
        self._real = hashlib.sha256(data)
        self.count = 0

    def update(self, data: bytes) -> None:
        self.count += len(data)
        self._real.update(data)

    def hexdigest(self) -> str:
        return self._real.hexdigest()

    def copy(self) -> "CountingHash":
        clone = CountingHash()
        clone._real = self._real.copy()
        clone.count = self.count
